function minEatingSpeed(piles, h) {
  let low = 1;
  let high = Math.max(...piles);

  const hoursNeeded = (speed) =>
    piles.reduce((sum, pile) => sum + Math.ceil(pile / speed), 0);

  while (low < high) {
    const mid = Math.floor((low + high) / 2);
    if (hoursNeeded(mid) <= h) high = mid;
    else low = mid + 1;
  }
  return low;
}
